package mapper;import entity.NhomKhachHang;import java.sql.ResultSet;import java.sql.SQLException;public class NhomKhachHangMapper implements RowMapper<NhomKhachHang> {    @Override    public NhomKhachHang mapper(ResultSet rs) {        try {            String maNhom = rs.getString("maNhom");            String tenNhom = rs.getString("tenNhom");            return new NhomKhachHang(maNhom, tenNhom);        } catch (SQLException e) {            return null;        }    }}